ed, modelMetadata = () => undefined, historySource = undefined, speed = undefined, trace = () => {}, phoneReturnMs = PHONE_RETURN_MS, userAgent, appServerUserAgent = userAgent, configFile = undefined, voice = undefined }) {\n  const subscribers = new Map() // threadId -> Set<notify>\n  const threadSources = new Map() // threadId -> the source the phone named when it created the thread (\"user\", \"realtime_voice\", ...)\n  const active = new Map() // threadId -> { turn }\n  const queues = new Map() // threadId -> QueuedSubmission[]\n  const starting = new Map() // synchronous admission reservations, before the first await\n  let catalog\n\n  const service = () => {\n    const value = controller()\n    if (!value) throw new RpcError(-32603, 'DSH session service is unavailable in this profile')\n    return value\n  }\n  const arrivals = new Map() // threadId -> Set<() => void>, woken when a phone opens the thread\n  const openedBy = new Map() // clientId -> Map<threadId, last time one of its connections had the thread open>\n  const subscribe = (threadId, notify) => {\n    const set = subscribers.get(threadId) ?? new Set()\n    // One phone has one live stream per thread: an older stream of the same phone no longer gets (and doubles) the updates.\n    if (notify.clientId) for (const other of [...set]) if (other !== notify && other.clientId === notify.clientId) set.delete(other)\n    set.add(notify)\n    subscribers.set(threadId, set)\n    if (notify.clientId) {\n      const opened = openedBy.get(notify.clientId) ?? new Map()\n      opened.set(threadId, Date.now())\n      openedBy.set(notify.clientId, opened)\n    }\n    for (const wake of arrivals.get(threadId) ?? []) wake()\n  }\n  /** Wait until a phone opens the thread again, the signal aborts, or the time runs out. */\n  const phoneReturns = (threadId, ms, signal) => new Promise(resolve => {\n    const set = arrivals.get(threadId) ?? new Set()\n    arrivals.set(threadId, set)\n    const done = value => { clearTime